module m_rp_global_var
    use m_common_global_var
    implicit none
    save

    !> One whole-run cache entry for StorCleanHandle.f90 (test_stor_clean),
    !> RP-only: the storage term never reaches FCC's ex record, so this
    !> lives beside Test rather than in m_typedef.f90's shared types.
    type :: StorCacheEntryType
        character(10) :: date
        character(5) :: time
        real(kind = dbl) :: strg(GHGNumVar)
    end type StorCacheEntryType
    type(StorCacheEntryType), allocatable :: StorCache(:)
    integer :: StorCacheN = 0

    !> Gas slots the FLUXNET header declared columns for, frozen as it is
    !> written.
    !>
    !> The header is written once, before the first DefineE2Set of the run, so
    !> E2Col is not in its final state yet; the row writers run afterwards,
    !> when it is. Deriving the column set separately in each place lets them
    !> disagree, and produces rows that do not match their own header. The row
    !> writers iterate these lists rather than re-deriving.
    integer :: FluxnetGasSlots(GHGNumVar) = 0
    integer :: nFluxnetGasSlots = 0
    integer :: FluxnetInstrSlots(GHGNumVar) = 0
    integer :: nFluxnetInstrSlots = 0
    !> Width of the fixed part of the FLUXNET row, counted from the header as
    !> it is built rather than written down twice. WriteOutFluxnetOnlyBiomet
    !> pads skipped periods to this width; it used to carry its own literal,
    !> which had drifted four columns short of the header.
    integer :: nFluxnetFixedCols = 0
    !> How many custom variables the FLUXNET header names. A skipped period's
    !> row writes this many, not its own period's NumUserVar: where every raw
    !> file brings its own metadata, as GHG archives do, a period's count can
    !> differ from the one the header was written with.
    integer :: nFluxnetCustomVars = 0
    !> Whether InitFluxnetFile_rp has opened the FLUXNET file and written its
    !> header.
    logical :: FluxnetFileOpen = .false.
    !> Periods skipped before that happened, waiting for their rows.
    !>
    !> The header is written after the first period that imports data, because
    !> its custom-variable columns are only known then - and the width of every
    !> row with them, a skipped period's included. A period skipped earlier
    !> than that, as every period before the first raw file is, used to be
    !> written anyway, to a unit nobody had opened: gfortran sent the row to
    !> fort.132 in the working directory and the FLUXNET file never had it.
    !> Only what belongs to the period is kept here; the rest of the row is
    !> built when it is written, from the header's own layout.
    type :: DeferredFluxnetRowType
        character(10) :: start_date = ''
        character(5)  :: start_time = ''
        character(10) :: date = ''
        character(5)  :: time = ''
        logical :: daytime = .false.
        !> nbVars values, in the units the header names; empty if the period
        !> came before biomet was first read.
        real(kind = dbl), allocatable :: biomet(:)
    end type DeferredFluxnetRowType
    type(DeferredFluxnetRowType), allocatable :: DeferredFluxnetRows(:)
    integer :: nDeferredFluxnetRows = 0
    !> Column-name tag of each slot in FluxnetGasSlots. Taken from the project
    !> rather than E2Col, for the same reason as the slot list, and made unique
    !> so a site with two measurements of one species does not emit two columns
    !> of the same name.
    character(32) :: FluxnetGasTags(GHGNumVar) = ''
    character(32) :: FluxnetInstrTags(GHGNumVar) = ''
    !> Every gas the project *configures*, present or not, in slot order.
    !>
    !> Distinct from FluxnetGasSlots, which holds only the gases that actually
    !> have a column. The fixed part of the row carries a set of columns for
    !> each configured gas and writes the error value for one with no data -
    !> a project naming four gases of which one has no column still emits four
    !> sets. Sizing that part from the present-gas list instead would silently
    !> drop a column set and shift every field after it.
    integer :: FluxnetLayoutSlots(GHGNumVar) = 0
    integer :: nFluxnetLayoutSlots = 0
    character(32) :: FluxnetLayoutTags(GHGNumVar) = ''
    !> The required FLUXNET variables, in the order the layout places them.
    !> FluxnetLayoutGasSlots puts these first, so a layout position is enough
    !> to say which column a name belongs to - no slot needs resolving, and a
    !> site that measures none of them still names its columns correctly.
    character(3), parameter :: FluxnetRequiredOrder(3) = &
        (/ 'CO2', 'H2O', 'CH4' /)
    integer, parameter :: FluxnetCarbonPosition = 1
    integer, parameter :: FluxnetWaterPosition  = 2

    integer :: NumAllRow = 0
    integer :: NumSlowVar = 0
    integer :: MaxPeriodNumRecords
    !> The acquisition frequency Raw and MaxPeriodNumRecords are currently
    !> sized for. A GHG file's own metadata can say otherwise - a project may
    !> switch from 10 to 20 Hz part way - and a file that disagrees with it is
    !> not imported into the current period. Negative until the preamble sets it.
    real(kind = dbl) :: PeriodAcFreq = -1d0
    !> The rate the binned-spectra frequency grid was built for. A period
    !> faster than this has its binned spectra cut at this rate's Nyquist.
    real(kind = dbl) :: BinGridAcFreq = -1d0

    type :: DateTimeArrayType
        character(10) :: date
        character(5) :: time
        type(DateType) :: dt_time
    end type DateTimeArrayType

    real(kind = dbl) :: refCounts(GHGNumVar)

    character(11), parameter :: rp_app              = 'EddyFlow-RP'
    character(14), parameter :: SubDirStats         = 'eddyflow_stats'
    character(21), parameter :: SubDirRaw           = 'eddyflow_raw_datasets'
    character(19), parameter :: SubDirUserStats     = 'eddyflow_user_stats'
    character(22), parameter :: SubDirBinOgives     = 'eddyflow_binned_ogives'
    !> One 25-character name per selected variable, plus the anemometric
    !> four and a margin. Sized from the capacity rather than from a
    !> literal: the gas loop that fills it was widened to MaxNumGases and
    !> the 512 it used to be was not, so it overflowed past ~17 gases.
    character(RawHeaderLen) :: raw_out_header
    character(PathLen) :: StatsDir
    character(PathLen) :: UserStatsDir
    character(PathLen) :: RawDir
    character(PathLen) :: RawSubDir(7)
    character(PathLen) :: BinCospectraDir
    character(PathLen) :: BinOgivesDir
    character(PathLen) :: CospectraDir
    character(PathLen) :: CcfDir
    character(PathLen) :: St1_Path
    character(PathLen) :: St2_Path
    character(PathLen) :: St3_Path
    character(PathLen) :: St4_Path
    character(PathLen) :: St5_Path
    character(PathLen) :: St6_Path
    character(PathLen) :: St7_Path
    character(PathLen) :: UserSt1_Path
    character(PathLen) :: UserSt2_Path
    character(PathLen) :: UserSt3_Path
    character(PathLen) :: UserSt4_Path
    character(PathLen) :: UserSt5_Path
    character(PathLen) :: UserSt6_Path
    character(PathLen) :: UserSt7_Path
    character(PathLen) :: Biomet_Path
    character(PathLen) :: PlanarFit_Path
    character(PathLen) :: TimelagOpt_Path
    character(PathLen) :: PwbTimelagCache_Path
    character(PathLen) :: QCdetails_Path
    logical :: OutVarPresent(E2NumVar)
    logical :: TimeLagOptSelected
    logical :: SonicDataHasWBug

