    type(RPsetupType) :: RPsetup
    type(PFSetupType) :: PFSetup
    type(TOSetupType) :: TOSetup
    type(PWBSetupType) :: PWBSetup
    type(PWBResultType) :: PWBResult(E2NumVar)
