    !> against its own water, and neither is "the" partition.
    integer :: nCecPairs
    type (CECResolvedPairType) :: CecPairList(MaxNumCecPairs)
    type (CECDescriptorType) :: CECDescriptor(MaxNumCecPairs)
    type (CECFluxType) :: CECFlux(MaxNumCecPairs)
    type (BurbaType):: Burba
    type (BurbaParType) :: BurbaPar
    type (StorType) :: Stor
    !> One per gas - see the ExType twin for why.
    type (Mul7700Type)   :: Mul7700(GHGNumVar)

    !> Embedded biomet data variables
    logical, allocatable :: BiometCTagFound(:)
    logical, allocatable :: BiometNTagFound(:)
    type(Text), allocatable :: BiometCTags(:)
    type(Numerical), allocatable :: BiometNTags(:)
    !> Whether the main pass met an embedded biomet table at all, and whether
    !> any of them gave a value - not a record: a logger that writes its
    !> half-hourly value on the first one-minute row and -9999 on the other
    !> 29 gives 29 records and no value once a biomet_header_rows one larger
    !> than the file's header has taken that first row as header. Every
    !> period then reports its records imported and every biomet output is
    !> -9999, with nothing naming why. The end of the run says so once. A
    !> production worker hands both back.
    logical :: EmbBiometTableSeen = .false.
    logical :: EmbBiometValueSeen = .false.

    !> What the last LangfordNoise call measured besides its random error:
    !> the mean and population SD of the far-lag cross-covariance and the
    !> covariance at the centre lag. Error where nothing was measured.
    !> LodLangford15 copies them out when out_lod_noise_stats is on.
    real(kind = dbl) :: LangfordNoiseMean(E2NumVar)
    real(kind = dbl) :: LangfordNoiseSd(E2NumVar)
    real(kind = dbl) :: LangfordNoisePeak(E2NumVar)

    !> Dynamic metadata
    type(DynMDType) :: DynamicMetadata
    integer :: DynamicMetadataOrder(MaxRowFields)
    !> Header column of each per-gas field, by gas slot; nint(error) where the
    !> file has none. The fixed DynamicMetadataOrder above covers the four
    !> historical analysers only - its index table stops at gas4_irga_tau -
    !> so a fifth gas had no way to be named in a dynamic metadata file at all.
    integer :: DynMDGasOrder(GHGNumVar, nDynMDGasFields)

